const LANGS=[['pt','IDIOMA: PORTUGUÊS'],['en','LANGUAGE: ENGLISH'],['es','IDIOMA: ESPAÑOL']];
const I18N_RX=I18N.pats.map(p=>[new RegExp(p[0]),p[1],p[2]]);
let TRC=new Map(),TRL='';
function guessLang(){try{const l=(navigator.language||'pt').toLowerCase();return l.startsWith('pt')?'pt':l.startsWith('es')?'es':'en';}catch(e){return 'pt';}}
function curLang(){return (save&&save.opt&&save.opt.lang)||'pt';}
function trExact(s,k){const e=I18N.exact[s];return e?e[k]:s;}
function tr(s){s=String(s);const L=curLang();if(L==='pt'||!s)return s;if(L!==TRL){TRC=new Map();TRL=L;}const c=TRC.get(s);if(c!==undefined)return c;
 const k=L==='en'?0:1;let out=I18N.exact[s]?I18N.exact[s][k]:null;
 if(out==null&&/^(ATQ|DEF|VEL|ESP|ESQ) [+−-]/.test(s))out=s.replace(/\b(ATQ|VEL|ESP|ESQ)\b/g,w=>trExact(w,k));
 if(out==null){out=s;for(const [rx,en,es] of I18N_RX){const m=rx.exec(s);if(m){out=(k?es:en).replace(/\{(\d)\}/g,(_,n)=>trExact(m[+n+1]||'',k));break;}}}
 if(out===s&&/^(ATQ|DEF|VEL|ESP|ESQ) [+−-]/.test(s))out=s.replace(/\b(ATQ|VEL|ESP|ESQ)\b/g,w=>trExact(w,k));
 if(out===s&&window.__trLog)window.__trLog.add(s);if(TRC.size>4000)TRC.clear();TRC.set(s,out);return out;}
